//! GPU-брутфорс через wgpu (Vulkan).
//!
//! Кандидаты генерируются прямо на видеокарте (по индексам пространства,
//! та же логика, что `combo_from_index` на CPU), хешируются WGSL-ядром
//! и сверяются с целями. Найденные индексы возвращаются на CPU, где из них
//! восстанавливается открытый текст через `WorkRef::candidate`.

use crate::hash::HashType;

/// Максимум целей в одном запуске шейдера.
const MAX_TARGETS: usize = 64;
/// Ёмкость буфера результатов (индексов найденного).
const RESULTS_CAPACITY: u32 = 1048576;
/// Максимальная длина маски (кандидат до 55 байт — один блок MD5/SHA*).
const MAX_MASK_LEN: usize = 64;
/// Максимальный суммарный размер чарсетов маски.
const MAX_CHARSET_DATA: usize = 256 * MAX_MASK_LEN;
/// Максимум индексов за один dispatch: 65535 workgroups × 256 инвокаций.
const MAX_DISPATCH_INDEX: u64 = 65535 * 256;

/// Параметры, передаваемые в uniform-буфер шейдера.
#[repr(C)]
#[derive(Clone, Copy)]
struct Params {
    batch_start: u64,
    batch_len: u32,
    mask_len: u32,
    num_targets: u32,
    digest_words: u32,
}

/// GPU-контекст: устройство, очередь, пайплайны хешей.
#[derive(Clone)]
pub struct GpuContext {
    device: wgpu::Device,
    queue: wgpu::Queue,
    md5_pipeline: wgpu::ComputePipeline,
    sha1_pipeline: wgpu::ComputePipeline,
    sha256_pipeline: wgpu::ComputePipeline,
    sha512_pipeline: wgpu::ComputePipeline,
    bind_group_layout: wgpu::BindGroupLayout,
}

impl GpuContext {
    /// Инициализация: instance → adapter → device → queue.
    pub fn new() -> Result<GpuContext, String> {
        let instance = wgpu::Instance::default();
        let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            compatible_surface: None,
            force_fallback_adapter: false,
            apply_limit_buckets: false,
        }))
        .map_err(|e| format!("не найден Vulkan-адаптер (GPU): {}", e))?;

        if !adapter
            .features()
            .contains(wgpu::Features::SHADER_INT64)
        {
            return Err(format!(
                "GPU {} не поддерживает 64-битные целые в шейдерах (SHADER_INT64) — нужен для больших пространств",
                adapter.get_info().name
            ));
        }

        let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor {
            label: Some("rust-hashcat gpu"),
            required_features: wgpu::Features::SHADER_INT64,
            required_limits: wgpu::Limits::default(),
            experimental_features: wgpu::ExperimentalFeatures::default(),
            memory_hints: wgpu::MemoryHints::Performance,
            trace: wgpu::Trace::Off,
        }))
        .map_err(|e| format!("не удалось создать устройство: {}", e))?;

        let md5_shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("md5 kernel"),
            source: wgpu::ShaderSource::Wgsl(include_str!("shaders/md5.wgsl").into()),
        });
        let sha1_shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("sha1 kernel"),
            source: wgpu::ShaderSource::Wgsl(include_str!("shaders/sha1.wgsl").into()),
        });
        let sha256_shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("sha256 kernel"),
            source: wgpu::ShaderSource::Wgsl(include_str!("shaders/sha256.wgsl").into()),
        });
        let sha512_shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("sha512 kernel"),
            source: wgpu::ShaderSource::Wgsl(include_str!("shaders/sha512.wgsl").into()),
        });

        let bind_group_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("crack bind layout"),
            entries: &[
                wgpu::BindGroupLayoutEntry {
                    binding: 0,
                    visibility: wgpu::ShaderStages::COMPUTE,
                    ty: wgpu::BindingType::Buffer {
                        ty: wgpu::BufferBindingType::Uniform,
                        has_dynamic_offset: false,
                        min_binding_size: None,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 1,
                    visibility: wgpu::ShaderStages::COMPUTE,
                    ty: wgpu::BindingType::Buffer {
                        ty: wgpu::BufferBindingType::Storage { read_only: true },
                        has_dynamic_offset: false,
                        min_binding_size: None,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 2,
                    visibility: wgpu::ShaderStages::COMPUTE,
                    ty: wgpu::BindingType::Buffer {
                        ty: wgpu::BufferBindingType::Storage { read_only: true },
                        has_dynamic_offset: false,
                        min_binding_size: None,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 3,
                    visibility: wgpu::ShaderStages::COMPUTE,
                    ty: wgpu::BindingType::Buffer {
                        ty: wgpu::BufferBindingType::Storage { read_only: true },
                        has_dynamic_offset: false,
                        min_binding_size: None,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 4,
                    visibility: wgpu::ShaderStages::COMPUTE,
                    ty: wgpu::BindingType::Buffer {
                        ty: wgpu::BufferBindingType::Storage { read_only: true },
                        has_dynamic_offset: false,
                        min_binding_size: None,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 5,
                    visibility: wgpu::ShaderStages::COMPUTE,
                    ty: wgpu::BindingType::Buffer {
                        ty: wgpu::BufferBindingType::Storage { read_only: false },
                        has_dynamic_offset: false,
                        min_binding_size: None,
                    },
                    count: None,
                },
            ],
        });

        let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("crack pipeline layout"),
            bind_group_layouts: &[Some(&bind_group_layout)],
            immediate_size: 0,
        });

        let md5_pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("md5 crack pipeline"),
            layout: Some(&pipeline_layout),
            module: &md5_shader,
            entry_point: Some("main"),
            compilation_options: Default::default(),
            cache: None,
        });
        let sha1_pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("sha1 crack pipeline"),
            layout: Some(&pipeline_layout),
            module: &sha1_shader,
            entry_point: Some("main"),
            compilation_options: Default::default(),
            cache: None,
        });
        let sha256_pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("sha256 crack pipeline"),
            layout: Some(&pipeline_layout),
            module: &sha256_shader,
            entry_point: Some("main"),
            compilation_options: Default::default(),
            cache: None,
        });
        let sha512_pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("sha512 crack pipeline"),
            layout: Some(&pipeline_layout),
            module: &sha512_shader,
            entry_point: Some("main"),
            compilation_options: Default::default(),
            cache: None,
        });

        Ok(GpuContext {
            device,
            queue,
            md5_pipeline,
            sha1_pipeline,
            sha256_pipeline,
            sha512_pipeline,
            bind_group_layout,
        })
    }

    /// Перебирает маску по индексам `[start, end)`, возвращает индексы
    /// кандидатов, чей digest совпал с одной из `targets`.
    ///
    /// `positions` — чарсеты по позициям маски (как `charset::parse_mask`).
    pub fn crack_mask(
        &self,
        ht: HashType,
        positions: &[Vec<u8>],
        targets: &[Vec<u8>],
        start: u64,
        end: u64,
    ) -> Result<Vec<u64>, String> {
        let mask_len = positions.len();
        if mask_len == 0 || mask_len > MAX_MASK_LEN {
            return Err(format!("длина маски {} вне диапазона 1..={}", mask_len, MAX_MASK_LEN));
        }
        if mask_len > 55 {
            return Err(format!(
                "GPU-брутфорс поддерживает маски до 55 символов (одноблочный хеш), а задано {}",
                mask_len
            ));
        }
        let batch_len = end - start;
        if batch_len == 0 {
            return Ok(Vec::new());
        }
        if batch_len > u32::MAX as u64 {
            return Err(format!("батч {} превышает лимит u32", batch_len));
        }
        if batch_len > MAX_DISPATCH_INDEX {
            return Err(format!(
                "батч {} превышает лимит одного dispatch ({}) — разбейте диапазон",
                batch_len, MAX_DISPATCH_INDEX
            ));
        }
        let num_targets = targets.len();
        if num_targets == 0 || num_targets > MAX_TARGETS {
            return Err(format!("целей должно быть 1..={}", MAX_TARGETS));
        }

        let digest_words = match ht {
            HashType::Md5 => 4,
            HashType::Sha1 => 5,
            HashType::Sha256 => 8,
            HashType::Sha512 => 16,
            HashType::Yescrypt => unreachable!("yescrypt не поддерживается на GPU"),
        };

        // Чарсеты: каждый символ — отдельный u32 (WGSL array<u32> индексируется
        // по элементам, а не по байтам). starts — смещения в элементах.
        let mut charset_u32: Vec<u32> = Vec::new();
        let mut lens = vec![0u32; MAX_MASK_LEN];
        let mut starts = vec![0u32; MAX_MASK_LEN];
        for (i, pos) in positions.iter().enumerate() {
            starts[i] = charset_u32.len() as u32;
            lens[i] = pos.len() as u32;
            charset_u32.extend(pos.iter().map(|&b| b as u32));
        }
        if charset_u32.len() > MAX_CHARSET_DATA {
            return Err(format!(
                "суммарный размер чарсетов {} превышает лимит {}",
                charset_u32.len(),
                MAX_CHARSET_DATA
            ));
        }

        let mut targets_data = vec![0u32; MAX_TARGETS * digest_words];
        for (i, t) in targets.iter().enumerate() {
            for w in 0..digest_words {
                let mut word = 0u32;
                for k in 0..4 {
                    word |= (t[w * 4 + k] as u32) << (k * 8);
                }
                targets_data[i * digest_words + w] = word;
            }
        }

        let params = Params {
            batch_start: start as u64,
            batch_len: batch_len as u32,
            mask_len: mask_len as u32,
            num_targets: num_targets as u32,
            digest_words: digest_words as u32,
        };

        // Буферы.
        let params_buf = self.make_buffer(
            "params",
            std::mem::size_of::<Params>() as u64,
            wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        );
        let charset_buf = self.make_buffer(
            "charset",
            (charset_u32.len() * 4) as u64,
            wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_DST,
        );
        let lens_buf = self.make_buffer(
            "lens",
            (lens.len() * 4) as u64,
            wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_DST,
        );
        let starts_buf = self.make_buffer(
            "starts",
            (starts.len() * 4) as u64,
            wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_DST,
        );
        let targets_buf = self.make_buffer(
            "targets",
            (targets_data.len() * 4) as u64,
            wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_DST,
        );
        let results_buf = self.make_buffer(
            "results",
            (1 + RESULTS_CAPACITY as usize * 2) as u64 * 4,
            wgpu::BufferUsages::STORAGE
                | wgpu::BufferUsages::COPY_SRC
                | wgpu::BufferUsages::COPY_DST,
        );
        let staging_buf = self.make_buffer(
            "staging",
            (1 + RESULTS_CAPACITY as usize * 2) as u64 * 4,
            wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        );

        // Пишем данные.
        let params_bytes: &[u8] = unsafe {
            std::slice::from_raw_parts(
                (&params as *const Params) as *const u8,
                std::mem::size_of::<Params>(),
            )
        };
        self.queue.write_buffer(&params_buf, 0, params_bytes);
        let charset_bytes: &[u8] = unsafe {
            std::slice::from_raw_parts(charset_u32.as_ptr() as *const u8, charset_u32.len() * 4)
        };
        self.queue.write_buffer(&charset_buf, 0, charset_bytes);
        let lens_bytes: &[u8] =
            unsafe { std::slice::from_raw_parts(lens.as_ptr() as *const u8, lens.len() * 4) };
        self.queue.write_buffer(&lens_buf, 0, lens_bytes);
        let starts_bytes: &[u8] =
            unsafe { std::slice::from_raw_parts(starts.as_ptr() as *const u8, starts.len() * 4) };
        self.queue.write_buffer(&starts_buf, 0, starts_bytes);
        let targets_bytes: &[u8] = unsafe {
            std::slice::from_raw_parts(targets_data.as_ptr() as *const u8, targets_data.len() * 4)
        };
        self.queue.write_buffer(&targets_buf, 0, targets_bytes);
        self.queue.write_buffer(&results_buf, 0, &[0u8; 4]);

        let bind_group = self.device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("crack bind group"),
            layout: &self.bind_group_layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: params_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: charset_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: lens_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 3,
                    resource: starts_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 4,
                    resource: targets_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 5,
                    resource: results_buf.as_entire_binding(),
                },
            ],
        });

        let pipeline = self.pipeline_for(ht);

        let mut encoder = self
            .device
            .create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
        {
            let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
                label: Some("crack pass"),
                timestamp_writes: None,
            });
            pass.set_pipeline(pipeline);
            pass.set_bind_group(0, &bind_group, &[]);
            // Лимит WebGPU: 65535 workgroups на один dispatch; batch_len
            // ограничен MAX_DISPATCH_INDEX выше, поэтому одного dispatch достаточно.
            pass.dispatch_workgroups((batch_len as u32).div_ceil(256), 1, 1);
        }
        encoder.copy_buffer_to_buffer(
            &results_buf,
            0,
            &staging_buf,
            0,
            (1 + RESULTS_CAPACITY as usize * 2) as u64 * 4,
        );
        self.queue.submit(Some(encoder.finish()));

        // Читаем результаты: [0]=число пар, далее пары (lo, hi).
        let slice = staging_buf.slice(..);
        let (tx, rx) = std::sync::mpsc::channel();
        slice.map_async(wgpu::MapMode::Read, move |res| {
            let _ = tx.send(res);
        });
        self.device
            .poll(wgpu::PollType::wait_indefinitely())
            .map_err(|e| format!("wgpu poll: {}", e))?;
        rx.recv()
            .map_err(|_| "wgpu map: канал закрыт".to_string())?
            .map_err(|e| format!("wgpu map: {}", e))?;

        let data = slice
            .get_mapped_range()
            .map_err(|e| format!("wgpu map read: {:?}", e))?;
        let count = u32::from_le_bytes([data[0], data[1], data[2], data[3]]) as usize;
        let mut found = Vec::with_capacity(count);
        for i in 0..count {
            let off = 4 + i * 8;
            let lo = u32::from_le_bytes([data[off], data[off + 1], data[off + 2], data[off + 3]]);
            let hi = u32::from_le_bytes([
                data[off + 4],
                data[off + 5],
                data[off + 6],
                data[off + 7],
            ]);
            found.push(((hi as u64) << 32) | lo as u64);
        }
        drop(data);
        staging_buf.unmap();
        Ok(found)
    }

    fn pipeline_for(&self, ht: HashType) -> &wgpu::ComputePipeline {
        match ht {
            HashType::Md5 => &self.md5_pipeline,
            HashType::Sha1 => &self.sha1_pipeline,
            HashType::Sha256 => &self.sha256_pipeline,
            HashType::Sha512 => &self.sha512_pipeline,
            HashType::Yescrypt => unreachable!("yescrypt не поддерживается на GPU"),
        }
    }

    fn make_buffer(&self, label: &str, size: u64, usage: wgpu::BufferUsages) -> wgpu::Buffer {
        self.device.create_buffer(&wgpu::BufferDescriptor {
            label: Some(label),
            size,
            usage,
            mapped_at_creation: false,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::hash::hex_decode;

    /// Индекс кандидата в base-N (как combo_from_index).
    fn idx_in_charset(candidate: &[u8], charset: &[u8]) -> u64 {
        let mut idx = 0u64;
        for &b in candidate {
            let pos = charset.iter().position(|&c| c == b).unwrap();
            idx = idx * charset.len() as u64 + pos as u64;
        }
        idx
    }

    #[test]
    fn gpu_cracks_md5_pass_by_mask() {
        let ctx = GpuContext::new().expect("GPU должен инициализироваться");
        // MD5("pass") = 1a1dc91c907325c69271ddf0c944bc72
        let target = hex_decode("1a1dc91c907325c69271ddf0c944bc72").unwrap();
        let charset = b"abcdefghijklmnopqrstuvwxyz";
        let positions = vec![charset.to_vec(); 4];
        let total = charset.len().pow(4) as u64;
        let found = ctx
            .crack_mask(HashType::Md5, &positions, &[target], 0, total)
            .unwrap();
        let idx_pass = idx_in_charset(b"pass", charset);
        assert!(
            found.contains(&idx_pass),
            "индекс 'pass' ({}) должен быть среди найденных: {:?}",
            idx_pass,
            found
        );
    }

    #[test]
    fn gpu_cracks_md5_pass_in_large_space() {
        // Проверка в пространстве ?l^8 (208 млрд): индекс 264126 — это строка
        // "aaaapass" (4 старших 'a' + "pass" в младших разрядах). Батч [0, 1_000_000)
        // содержит её; главное — u64-арифметика работает на больших пространствах.
        let ctx = GpuContext::new().expect("GPU должен инициализироваться");
        let target = crate::hash::hash_bytes(HashType::Md5, b"aaaapass");
        let charset = b"abcdefghijklmnopqrstuvwxyz";
        let positions = vec![charset.to_vec(); 8];
        let found = ctx
            .crack_mask(HashType::Md5, &positions, &[target], 0, 1_000_000)
            .unwrap();
        let idx_pass = idx_in_charset(b"aaaapass", charset); // 264126
        assert!(
            found.contains(&idx_pass),
            "индекс 'aaaapass' ({}) должен быть среди найденных: {:?}",
            idx_pass,
            found
        );
    }

