            idx_pass,
            found
        );
    }

    #[test]
    fn gpu_cracks_md5_mixed_charsets() {
        // Гетерогенная маска ?l?d?l?d: 'a1b2' → индекс = ((0*10+1)*26+1)*10+2 = 292
        let ctx = GpuContext::new().expect("GPU должен инициализироваться");
        let target = crate::hash::hash_bytes(HashType::Md5, b"a1b2");
        let lower = b"abcdefghijklmnopqrstuvwxyz";
        let digits = b"0123456789";
        let positions = vec![lower.to_vec(), digits.to_vec(), lower.to_vec(), digits.to_vec()];
        let total = 26u64 * 10 * 26 * 10;
        let found = ctx
            .crack_mask(HashType::Md5, &positions, &[target], 0, total)
            .unwrap();
        // Индекс "a1b2": a=0 (старший разряд), 1=1, b=1, 2=2 → ((0*10+1)*26+1)*10+2 = 272
        assert!(
            found.contains(&272),
            "индекс 'a1b2' (272) должен быть среди найденных: {:?}",
            found
        );
    }

    #[test]
    fn gpu_cracks_md5_with_large_offset() {
        // Индекс "zzzzpass" в ?l^8 ≈ 2.088e11 > u32::MAX — до перевода MD5
        // на u64-индексы batch_start обрезался и тест падал.
        let ctx = GpuContext::new().expect("GPU должен инициализироваться");
        let charset = b"abcdefghijklmnopqrstuvwxyz";
        let positions = vec![charset.to_vec(); 8];
        let idx_pass = idx_in_charset(b"zzzzpass", charset);
        let target = crate::hash::hash_bytes(HashType::Md5, b"zzzzpass");
        let start = idx_pass - 1000;
        let found = ctx
            .crack_mask(HashType::Md5, &positions, &[target], start, idx_pass + 1)
            .unwrap();
        assert!(
            found.contains(&idx_pass),
            "индекс 'zzzzpass' ({}) должен быть среди найденных: {:?}",
            idx_pass,
            found
        );
    }

    #[test]
    fn gpu_shaders_match_cpu_for_various_lengths() {
        // WGSL-ядра должны давать те же digest'ы, что CPU-эталон (crates md-5/sha1/sha2,
        // проверенные в hash::self_test на известных векторах). Прогоняем длины вплоть
        // до границы одноблочного хеша (55 байт) — padding и границы слов различаются.
        let ctx = GpuContext::new().expect("GPU должен инициализироваться");
        let lower = b"abcdefghijklmnopqrstuvwxyz";
        for ht in [
            HashType::Md5,
            HashType::Sha1,
            HashType::Sha256,
            HashType::Sha512,
        ] {
            for &len in &[1usize, 2, 3, 4, 5, 8, 13, 16, 24, 31, 32, 47, 48, 55] {
                let candidate = vec![b'a'; len];
                let target = crate::hash::hash_bytes(ht, &candidate);
                let positions = vec![lower.to_vec(); len];
                let found = ctx
                    .crack_mask(ht, &positions, &[target], 0, 100_000)
                    .unwrap();
                assert!(
                    found.contains(&0),
                    "{} длина {}: индекс 0 не найден, found={:?}",
                    ht.name(),
                    len,
                    found
                );
            }
        }
    }

    #[test]
    fn gpu_no_false_positives() {
        // Единственная цель в пространстве ?d^3 (1000 комбинаций) — должен найтись
        // ровно индекс 500, никакие другие (иначе шейдер хеширует неверно).
        let ctx = GpuContext::new().expect("GPU должен инициализироваться");
        let digits = b"0123456789";
        let positions = vec![digits.to_vec(); 3];
        for ht in [
            HashType::Md5,
            HashType::Sha1,
            HashType::Sha256,
            HashType::Sha512,
        ] {
            let target = crate::hash::hash_bytes(ht, b"500");
            let found = ctx
                .crack_mask(ht, &positions, &[target], 0, 1000)
                .unwrap();
            assert_eq!(found, vec![500], "{}: ожидался только индекс 500", ht.name());
        }
    }

    #[test]
    fn gpu_multi_target_exhaustive_small_range() {
        // 64 цели (максимум для GPU) из первых 64 индексов пространства ?a^4.
        // Если генерация кандидатов или хеширование в шейдере неверны — часть
        // индексов не найдётся или найдутся лишние.
        let ctx = GpuContext::new().expect("GPU должен инициализироваться");
        let charset_a = crate::charset::parse_charset("?a").unwrap(); // Charset (символьный)
        // Символьная версия — для combo_from_index (генерация целей).
        let positions_cs: Vec<crate::charset::Charset> = vec![charset_a.clone(); 4];
        // Байтовая версия — для crack_mask (GPU, только ASCII).
        let byte_charset: Vec<u8> = charset_a.iter().map(|s| s[0]).collect();
        let positions = vec![byte_charset; 4];
        for ht in [
            HashType::Md5,
            HashType::Sha1,
            HashType::Sha256,
            HashType::Sha512,
        ] {
            let mut targets: Vec<Vec<u8>> = Vec::new();
            for i in 0u128..64 {
                let cand = crate::charset::combo_from_index(&positions_cs, i);
                targets.push(crate::hash::hash_bytes(ht, &cand));
            }
            let mut found = ctx
                .crack_mask(ht, &positions, &targets, 0, 500)
                .unwrap();
            found.sort_unstable();
            let expected: Vec<u64> = (0u64..64).collect();
            assert_eq!(found, expected, "{}: не все 64 индекса найдены", ht.name());
        }
    }

    #[test]
    fn gpu_binary_bytes_via_charset_b() {
        // ?b — все 256 байтов. Проверяем крайние значения: [0x00 x4] (индекс 0)
        // и [0xFF x4] (индекс 256^4-1 = 4294967295, за пределами u32) — MD5-батч
        // со смещением за u32::MAX работает только после перевода индексов на u64.
        let ctx = GpuContext::new().expect("GPU должен инициализироваться");
        let charset_b = crate::charset::charset_all_bytes();
        let positions = vec![charset_b; 4];
        let idx_ff: u64 = 256u64.pow(4) - 1;
        for ht in [
            HashType::Md5,
            HashType::Sha1,
            HashType::Sha256,
            HashType::Sha512,
        ] {
            let t_zero = crate::hash::hash_bytes(ht, &[0x00u8; 4]);
            let t_ff = crate::hash::hash_bytes(ht, &[0xFFu8; 4]);
            let found_zero = ctx
                .crack_mask(ht, &positions, &[t_zero], 0, 1000)
                .unwrap();
            assert!(
                found_zero.contains(&0),
                "{}: [00 00 00 00] (индекс 0) не найден",
                ht.name()
            );
            let found_ff = ctx
                .crack_mask(ht, &positions, &[t_ff], idx_ff - 100, idx_ff + 1)
                .unwrap();
            assert!(
                found_ff.contains(&idx_ff),
                "{}: [FF FF FF FF] (индекс {}) не найден",
                ht.name(),
                idx_ff
            );
        }
    }

    #[test]
    fn gpu_rejects_oversized_batch() {
        // Батч > 65535×256 индексов нельзя обработать одним dispatch'ом —
        // повторный dispatch в WebGPU стартует с тех же индексов (дубликаты).
        // crack_mask должен вернуть ошибку, а не тихо дублировать.
        let ctx = GpuContext::new().expect("GPU должен инициализироваться");
        let lower = b"abcdefghijklmnopqrstuvwxyz";
        let positions = vec![lower.to_vec(); 8];
        let target = crate::hash::hash_bytes(HashType::Md5, b"aaaaaaaa");
        let res = ctx.crack_mask(HashType::Md5, &positions, &[target], 0, 20_000_000);
        assert!(res.is_err(), "ожидалась ошибка для батча > 16 777 215, получено {:?}", res);
    }
